        $script:md | Should -Match '\| Failed \| 1 \|'
        $script:md | Should -Match '\| Skipped \| 1 \|'
        $script:md | Should -Match '\| Total \| 7 \|'
        $script:md | Should -Match '\| Duration \| 3.3s \|'
        $script:md | Should -Match '\| Runs \| 3 \|'
